traces.query:
PREFIX net: <http://example.org/network#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?alarm ?label
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?dev ;
         rdfs:label ?label .
  ?dev a net:NetworkDevice ;
       rdfs:label "Edge Firewall FW1" .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?criticalAlarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "CRITICAL" .
}

PREFIX net: <http://example.org/network#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?alarm ?alarmLabel
WHERE {
  ?alarm a net:Alarm .
  ?alarm net:affectsDevice net:Router_Core .
  OPTIONAL { ?alarm rdfs:label ?alarmLabel . }
}

PREFIX net: <http://example.org/network#>
SELECT ?severity WHERE {
  net:Alarm_PacketDrop net:hasSeverity ?severity .
}

PREFIX net: <http://example.org/network#>
SELECT ?device (COUNT(?alarm) AS ?alarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?device .
}
GROUP BY ?device
ORDER BY DESC(?alarmCount)
LIMIT 1

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
}
ORDER BY ?time
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?mitreId WHERE {
  net:Incident_DDoS net:classifiedAs ?ap .
  ?ap net:mitreId ?mitreId .
}

PREFIX net: <http://example.org/network#>

SELECT ?deviceType
WHERE {
  net:Server_Web net:deviceType ?deviceType .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?alarmCount)
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "HIGH" .
}

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
  FILTER ( ?time > "2026-06-02T14:01:00"^^xsd:dateTime )
}

PREFIX net: <http://example.org/network#>
SELECT ?rootCauseAlarm ?alarmType ?severity ?device ?deviceType WHERE {
  # incident instance
  net:Incident_DDoS net:composedOf ?alarm .
  # find alarms that are not caused by any other alarm in the incident (root causes)
  FILTER NOT EXISTS {
    ?cause net:causallyLinkedTo ?alarm .
    net:Incident_DDoS net:composedOf ?cause .
  }
  BIND(?alarm AS ?rootCauseAlarm)
  OPTIONAL { ?alarm net:alarmType ?alarmType . }
  OPTIONAL { ?alarm net:hasSeverity ?severity . }
  OPTIONAL { ?alarm net:affectsDevice ?device .
             OPTIONAL { ?device net:deviceType ?deviceType . } }
}

PREFIX net: <http://example.org/network#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?root ?rootLabel WHERE {
  net:Alarm_WebTimeout net:causallyLinkedTo+ ?root .
  FILTER NOT EXISTS { ?prev net:causallyLinkedTo ?root }
  OPTIONAL { ?root rdfs:label ?rootLabel }
}

PREFIX net: <http://example.org/network#>
SELECT ?causeAlarm ?causeType WHERE {
  net:Alarm_Latency net:causallyLinkedTo ?causeAlarm .
  ?causeAlarm net:alarmType ?causeType .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         rdfs:label ?label .
  <http://example.org/network#Alarm_FirewallSpike> net:causallyLinkedTo+ ?alarm .
}

PREFIX net: <http://example.org/network#>

SELECT ?intermediateAlarm WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo+ ?intermediateAlarm .
  ?intermediateAlarm net:causallyLinkedTo+ net:Alarm_WebTimeout .
  FILTER(?intermediateAlarm != net:Alarm_FirewallSpike && ?intermediateAlarm != net:Alarm_WebTimeout)
}

PREFIX net: <http://example.org/network#>

SELECT (COUNT(?intermediate) AS ?pathExists) WHERE {
  <http://example.org/network#Alarm_CPU> net:causallyLinkedTo+ ?intermediate .
  FILTER(?intermediate = <http://example.org/network#Alarm_WebTimeout>)
}

PREFIX net: <http://example.org/network#>

SELECT (COUNT(*) AS ?pathCount) WHERE {
  net:Alarm_Latency net:causallyLinkedTo+ net:Alarm_WebTimeout .
}

PREFIX net: <http://example.org/network#>
SELECT ?rootAlarm ?device
WHERE {
  ?rootAlarm a net:Alarm .
  FILTER NOT EXISTS {
    ?anyAlarm net:causallyLinkedTo ?rootAlarm .
  }
  ?rootAlarm net:affectsDevice ?device .
}

PREFIX net: <http://example.org/network#>
SELECT ?direction WHERE {
  {
    net:Alarm_Latency net:causallyLinkedTo net:Alarm_PacketDrop .
    BIND("Latency causes PacketDrop" AS ?direction)
  }
  UNION
  {
    net:Alarm_PacketDrop net:causallyLinkedTo net:Alarm_Latency .
    BIND("PacketDrop causes Latency" AS ?direction)
  }
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm
WHERE {
  net:Alarm_PacketDrop net:correlatedWith ?alarm .
  FILTER NOT EXISTS { net:Alarm_PacketDrop net:causallyLinkedTo ?alarm }
}

PREFIX net: <http://example.org/network#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?device
WHERE {
  # Alarms that affect the core router R1
  ?alarmR1 net:affectsDevice net:Router_Core .

  # Candidate root‑cause alarm and its device
  ?rootAlarm net:affectsDevice ?device .

  # The root alarm must (transitively) cause every alarm on R1
  FILTER NOT EXISTS {
    ?alarmR1 net:affectsDevice net:Router_Core .
    FILTER NOT EXISTS {
      ?rootAlarm (net:causallyLinkedTo)+ ?alarmR1 .
    }
  }
}

PREFIX net: <http://example.org/network#>

SELECT ?downstreamAlarm ?label
WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo ?downstreamAlarm .
  ?downstreamAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>

SELECT ?avoidedAlarm
WHERE {
  net:Alarm_CPU net:causallyLinkedTo ?avoidedAlarm .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(DISTINCT ?downstream) AS ?preventedAlarms) WHERE {
  net:Alarm_PacketDrop net:causallyLinkedTo+ ?downstream .
  FILTER(?downstream != net:Alarm_PacketDrop)
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm ?alarmType ?severity
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
  ?alarm net:alarmType ?alarmType ;
         net:hasSeverity ?severity .
  FILTER (?alarm != net:Alarm_CPU)
  FILTER NOT EXISTS {
    net:Alarm_CPU net:causallyLinkedTo ?alarm .
  }
}

PREFIX net: <http://example.org/network#>

SELECT ?downstreamAlarm WHERE {
  net:Alarm_Latency net:causallyLinkedTo+ ?downstreamAlarm .
  FILTER(?downstreamAlarm = net:Alarm_WebTimeout)
}
